import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print('no')
        return

    n = int(data[0])
    m = int(data[1])

    if n == 0 or n == 1:
        print('yes')
        return

    edges = []
    idx = 2
    for i in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        edges.append((u, v))
        idx += 2

    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    root = None
    for node in adj:
        if len(adj[node]) == 1:
            root = node
            break

    if root is None:
        if len(adj) > 0:
            root = list(adj.keys())[0]
        else:
            print('yes')
            return

    left = {}
    right = {}
    parent = {}

    def build_tree(node, par):
        parent[node] = par
        children = [child for child in adj[node] if child != par]
        children.sort()
        if len(children) == 0:
            left[node] = None
            right[node] = None
        elif len(children) == 1:
            if par is not None:
                left[node] = children[0]
                right[node] = None
            else:
                left[node] = None
                right[node] = children[0]
        else:
            left[node] = children[0]
            right[node] = children[1]

        for child in [left[node], right[node]]:
            if child is not None:
                build_tree(child, node)

    build_tree(root, None)

    def is_symmetric(node_l, node_r):
        if node_l is None and node_r is None:
            return True
        if node_l is None or node_r is None:
            return False
        if left[node_l] != right[node_r]:
            return False
        if right[node_l] != left[node_r]:
            return False
        return is_symmetric(left[node_l], right[node_r]) and is_symmetric(right[node_l], left[node_r])

    if is_symmetric(left[root], right[root]):
        print('yes')
    else:
        print('no')

if __name__ == "__main__":
    main()
